"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["7466"],{23461(e){e.exports=JSON.parse('{"id":"FIN-1162","slug":"market-liquidity","term":"Market Liquidity","also_known_as":[],"difficulty":"Advanced","definition":"Market liquidity is the ease with which assets can be bought or sold in a market quickly, in large amounts and without significantly moving their price.","explanation":["A liquid market has many buyers and sellers, high trading volumes, narrow gaps between buying and selling prices and enough depth that large orders can be filled without large price changes. Major currency markets, large company shares and major government bonds are usually highly liquid.","An illiquid market has few participants, wide gaps between prices and little depth. Shares of small companies, some corporate bonds, property and private investments are less liquid.","For example, an investor can usually sell 100,000 worth of shares in a large international company within seconds at close to the quoted price, but selling the same amount of a small company\'s shares might take days and push the price down.","Market liquidity can change quickly. During periods of stress, buyers may disappear and liquidity can dry up even in normally liquid markets, as happened in some bond markets in March 2020. Investors often demand higher returns for holding less liquid assets, known as an illiquidity premium."],"note":"","total":1725,"prev":{"slug":"market-index","term":"Market Index"},"next":{"slug":"market-maker","term":"Market Maker"}}')}}]);